SELECT ?point ?tsid WHERE {
  ?point brick:isA brick:Electric_Power .
  ?point brick:isPointOf [ rdfs:label "AHU02" ] .
  ?point ref:hasExternalReference ?tsref .
  ?tsref ref:hasTimeseriesId ?tsid .
}

SELECT ?point ?type ?tsid WHERE {
  ?point ref:hasExternalReference ?tsref .
  ?tsref ref:hasTimeseriesId ?tsid .
  FILTER(strcontains(str(?point), "AHU02"))
  FILTER(strcontains(str(?point), "ower"))
}

SELECT ?point ?type WHERE {
  ?point a ?type .
  FILTER ( strcontains(STR(?point), "AHU02") && strcontains(STR(?point), "ower") )
}

