SELECT ?point ?type ?parent WHERE {
  ?point a ?type .
  ?point brick:isPointOf ?parent .
  FILTER ( strcontains(STR(?point), "AHU02") && !strcontains(STR(?point), "VAV") )
}

SELECT ?parent ?label WHERE {
  ?p a brick:Electric_Power_Sensor .
  ?p brick:isPointOf ?parent .
  OPTIONAL { ?parent rdfs:label ?label }
  FILTER ( strcontains(STR(?parent), "AHU02") )
}

SELECT ?point ?type ?parent ?label WHERE {
  ?point a ?type .
  ?point brick:isPointOf ?parent .
  OPTIONAL { ?parent rdfs:label ?label }
}

